19: export function searchProducts () {
20:   return (req: Request, res: Response, next: NextFunction) => {
21:     let criteria: any = req.query.q === 'undefined' ? '' : req.query.q ?? ''
22:     criteria = (criteria.length <= 200) ? criteria : criteria.substring(0, 200)
23:     models.sequelize.query(`SELECT * FROM Products WHERE ((name LIKE '%${criteria}%' OR description LIKE '%${criteria}%') AND deletedAt IS NULL) ORDER BY name`) 
24:       .then(([products]: any) => {
25:         const dataString = JSON.stringify(products)
26:         if (challengeUtils.notSolved(challenges.unionSqlInjectionChallenge)) { 
27:           let solved = true
28:           UserModel.findAll().then(data => {
29:             const users = utils.queryResultToJson(data)
30:             if (users.data?.length) {
31:               for (let i = 0; i < users.data.length; i++) {
32:                 solved = solved && utils.containsOrEscaped(dataString, users.data[i].email) && dataString.includes(users.data[i].password)
33:                 if (!solved) {
34:                   break
35:                 }
36:               }
37:               if (solved) {
38:                 challengeUtils.solve(challenges.unionSqlInjectionChallenge)
39:               }
40:             }
41:           }).catch((error: Error) => {
42:             next(error)
43:           })
44:         }
45:         if (challengeUtils.notSolved(challenges.dbSchemaChallenge)) {
46:           let solved = true
47:           void models.sequelize.query('SELECT sql FROM sqlite_master').then(([data]: any) => {
48:             const tableDefinitions = utils.queryResultToJson(data)
49:             if (tableDefinitions.data?.length) {
50:               for (let i = 0; i < tableDefinitions.data.length; i++) {
51:                 if (tableDefinitions.data[i].sql) {
52:                   solved = solved && utils.containsOrEscaped(dataString, tableDefinitions.data[i].sql)
