65:           products[i].name = req.__(products[i].name)
66:           products[i].description = req.__(products[i].description)
67:         }
68:         res.json(utils.queryResultToJson(products))
69:       }).catch((error: ErrorWithParent) => {
70:         next(error.parent)
71:       })
72:   }
73: }
